cat > src/slugkit/__init__.py <<'EOF'
"""slugkit: tiny slug helpers."""

import re
import unicodedata


def slugify(text: str) -> str:
    decomposed = unicodedata.normalize("NFKD", text)
    stripped = "".join(c for c in decomposed if not unicodedata.combining(c))
    slug = re.sub(r"[^a-z0-9]+", "-", stripped.lower()).strip("-")
    if not slug:
        raise ValueError("slug would be empty")
    return slug
EOF
mkdir tests
cat > tests/test_slugify.py <<'EOF'
import pytest

from slugkit import slugify


@pytest.mark.l4("C-1dfbe7d5")
def test_simple_phrase():
    assert slugify("Hello, World!") == "hello-world"


@pytest.mark.l4("C-773e3a78")
def test_accented_letters_transliterated():
    assert slugify("Crème Brûlée à Paris") == "creme-brulee-a-paris"


@pytest.mark.l4("C-a0d79e4d")
def test_non_latin_dropped():
    assert slugify("naïve 東京 café") == "naive-cafe"


@pytest.mark.l4("C-daf9f48c")
def test_empty_string_rejected():
    with pytest.raises(ValueError):
        slugify("")


@pytest.mark.l4("C-534dee75")
def test_only_symbols_rejected():
    with pytest.raises(ValueError):
        slugify("!!! ??? ---")
EOF
uv run pytest -q 2>&1 | tail -5

